uniform shader image;
uniform float2 size;
uniform float phase;
uniform float amount;
uniform float scale;
layout(color) uniform half4 tint;
float hash(float2 p){return fract(sin(dot(p,float2(127.1,311.7)))*43758.5453);}half4 effectMain(float2 coord){half4 c=image.eval(coord);float2 cell=floor(coord/scale);float2 f=fract(coord/scale)-0.5;float n=hash(cell);float2 drift=float2(sin(phase+n*6.28),cos(phase*0.7+n*9.0))*0.22;float d=length(f-drift);float dotp=(1.0-smoothstep(0.06,0.16,d))*step(1.0-amount,n);float pulse=0.5+0.5*sin(phase*3.0+n*6.28);return half4(clamp(c.rgb+tint.rgb*half(dotp*pulse)*c.a,half3(0),half3(1)),c.a);}
uniform float effectOpacity;
half4 main(float2 coord) {
    half4 original = image.eval(coord);
    half4 processed = effectMain(coord);
    return mix(original, processed, half(clamp(effectOpacity, 0.0, 1.0)));
}
